@pytest.mark.parametrize("kind", ["symlink", "hardlink", "outside", "directory"])
def test_source_must_be_one_regular_owned_local_file(tmp_path: Path, kind: str) -> None:
    settings = _settings(tmp_path)
    source = _source(settings)
    if kind == "symlink":
        target = source.with_name("link.avi")
        target.symlink_to(source)
        source = target
    elif kind == "hardlink":
        os.link(source, source.with_name("linked.avi"))
    elif kind == "outside":
        source = tmp_path / "outside.avi"
        source.write_bytes(b"RIFF" + b"\x00" * 4 + b"AVI ")
    else:
        source = source.with_name("directory.avi")
        source.mkdir()
    with pytest.raises(preparation.VideoPreparationError, match="invalid_source"):
        _prepare(source, settings)


