    monkeypatch.setattr(preparation, "_run", lambda *_args, **_kwargs: json.dumps(payload).encode())
    with pytest.raises(preparation.VideoPreparationError, match=code):
        preparation._probe(_source(settings), "/fixture/ffprobe", settings, float("inf"))


