def test_kernel_lock_rejects_overlap_and_recovers_without_deleting_inode(tmp_path: Path) -> None:
    settings = _settings(tmp_path)
    _source(settings)
    with preparation._preparation_lock(settings) as work:
        inode = (work / "prepare.lock").stat().st_ino
        with pytest.raises(preparation.VideoPreparationError, match="transcode_busy"):
            with preparation._preparation_lock(settings):
                pytest.fail("overlapping lock acquired")
    with preparation._preparation_lock(settings) as recovered:
        assert (recovered / "prepare.lock").stat().st_ino == inode


@pytest.mark.parametrize("kind", ["symlink", "hardlink"])
def test_shared_lock_rejects_unsafe_links(tmp_path: Path, kind: str) -> None:
    settings = _settings(tmp_path)
    _source(settings)
    work = settings.data_dir / ".video-preparation"
    work.mkdir()
    target = tmp_path / "outside.lock"
    target.write_bytes(b"fixture lock")
    if kind == "symlink":
        (work / "prepare.lock").symlink_to(target)
    else:
        os.link(target, work / "prepare.lock")
    with pytest.raises(preparation.VideoPreparationError, match="invalid_lock"):
        with preparation._preparation_lock(settings):
            pytest.fail("unsafe lock acquired")


