@pytest.mark.parametrize(
    "module_name",
    ["scripts.cleanup_media_before", "scripts.cleanup_non_crossing_stream_frames"],
)
def test_cleanup_preserves_all_video_assets_even_failed_unindexed_and_unknown_videos(
    tmp_path: Path, module_name: str
) -> None:
    from app.models.media import VideoAsset
    from app.services.video_retention import video_asset_media_urls

    cleanup = importlib.import_module(module_name)
    settings = _settings(tmp_path)
    original, playback, unowned = [_source(settings) for _ in range(3)]
    settings.frames_dir.mkdir(parents=True, exist_ok=True)
    retired = settings.frames_dir / "retired.jpg"
    protected = settings.frames_dir / "owned.jpg"
    retired.write_bytes(b"retired frame")
    protected.write_bytes(b"non-video protected reference")
    engine, sessions = _database(tmp_path)
    try:
        with sessions() as db:
            db.add_all(
                [
                    VideoAsset(
                        original_video_url=f"/data/videos/{original.name}",
                        playback_video_url=f"/data/videos/{playback.name}",
                        preparation_status="failed",
                    ),
                    VideoAsset(original_video_url="/data/frames/owned.jpg"),
                ]
            )
            db.commit()
            protected_urls = video_asset_media_urls(db)
            assert f"/data/videos/{original.name}" in protected_urls
            assert f"/data/videos/{playback.name}" in protected_urls
            removed = cleanup.remove_files(
                settings.data_dir,
                [
                    (f"/data/videos/{original.name}", f"/data/videos/{playback.name}"),
                    (f"/data/videos/{unowned.name}", "/data/frames/owned.jpg"),
                    ("/data/frames/retired.jpg", None),
                ],
                protected_urls,
            )
        assert removed == 1 and not retired.exists()
        assert (
            original.is_file() and playback.is_file() and unowned.is_file() and protected.is_file()
        )
    finally:
        engine.dispose()


def test_cleanup_legacy_schema_and_unsafe_file_targets_remain_safe(tmp_path: Path) -> None:
    from app.services.video_retention import remove_retired_image_files, video_asset_media_urls

    settings = _settings(tmp_path)
    settings.frames_dir.mkdir(parents=True)
    outside = tmp_path / "outside.jpg"
    outside.write_bytes(b"outside")
    (settings.frames_dir / "link.jpg").symlink_to(outside)
    os.link(outside, settings.frames_dir / "hardlink.jpg")
    (settings.frames_dir / "directory.jpg").mkdir()
    engine = create_engine(f"sqlite:///{tmp_path / 'legacy.sqlite'}")
    try:
        with sessionmaker(bind=engine)() as db:
            assert video_asset_media_urls(db) == frozenset()
        assert (
            remove_retired_image_files(
                settings.data_dir,
                [
                    ("/data/../outside.jpg", "/data/frames/../../outside.jpg"),
                    ("/data/frames/link.jpg", "/data/frames/hardlink.jpg"),
                    ("/data/frames/directory.jpg", "/data/frames/missing.jpg"),
                ],
            )
            == 0
        )
        assert outside.read_bytes() == b"outside"
        assert (settings.frames_dir / "link.jpg").is_symlink()
    finally:
        engine.dispose()
